-- MedLine: дерекқор үлгісі (MySQL 8+)
CREATE DATABASE IF NOT EXISTS medline_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE medline_db;
CREATE TABLE users(user_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(190) UNIQUE,phone VARCHAR(30) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('patient','doctor','admin') NOT NULL DEFAULT 'patient',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE specialties(specialty_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_kk VARCHAR(100) NOT NULL,name_ru VARCHAR(100) NOT NULL,description TEXT);
CREATE TABLE doctors(doctor_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,specialty_id INT UNSIGNED NOT NULL,full_name VARCHAR(150) NOT NULL,biography TEXT,experience_years TINYINT UNSIGNED NOT NULL DEFAULT 0,consultation_price DECIMAL(10,2) NOT NULL DEFAULT 0,rating DECIMAL(2,1) NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE SET NULL,FOREIGN KEY(specialty_id) REFERENCES specialties(specialty_id));
CREATE TABLE schedules(schedule_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,work_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,slot_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 30,is_available BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id) ON DELETE CASCADE,INDEX idx_schedule_doctor_date(doctor_id,work_date));
CREATE TABLE appointments(appointment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,schedule_id BIGINT UNSIGNED NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,status ENUM('pending','confirmed','cancelled','completed') NOT NULL DEFAULT 'pending',patient_note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id),FOREIGN KEY(schedule_id) REFERENCES schedules(schedule_id) ON DELETE SET NULL,INDEX idx_user_date(user_id,appointment_date),INDEX idx_doctor_time(doctor_id,appointment_date,appointment_time));
CREATE TABLE reviews(review_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(doctor_id) REFERENCES doctors(doctor_id) ON DELETE CASCADE);
